<?php

namespace Splicewire\Beam\Docs\PhpApi;

use Illuminate\Contracts\Auth\Authenticatable;
use Illuminate\Http\Request;
use Splicewire\Beam\Docs\Data\PhpApiSymbolData;
use Splicewire\Beam\Docs\Data\PhpApiSymbolInputData;
use Splicewire\Beam\Docs\Http\PhpApiReadGate;
use Splicewire\Beam\Particle\Attributes\ParticleOp;
use Splicewire\Beam\Particle\OperationKind;
use Splicewire\Beam\Particle\Subject\NoSubject;
use Splicewire\Beam\Routing\HttpMethod;

/**
 * `beam-docs.php-api-symbol` (php-api-reference slice 2), generated by `splicewire:beam:make:particle-op` and moved into
 * the package. Mounted at `GET beam/docs/php-api-symbol?fqn=` beside `docs.search`, behind
 * {@see PhpApiReadGate}; authorized exactly as {@see PhpApiIndexOp}.
 *
 * `fqn` is a KEY: it is looked up in the generated indexes and the file opened is the path the index row holds
 * ({@see PhpApiArtifact::symbol()}). It never forms a filesystem path; an FQN no index lists is the uniform 404.
 */
#[ParticleOp(
    resource: 'beam-docs',
    name: 'php-api-symbol',
    summary: 'One published symbol of the generated PHP API reference, by FQN.',
    kind: OperationKind::Read,
    ability: false,
    affordance: false,
    input: PhpApiSymbolInputData::class,
    output: PhpApiSymbolData::class,
    subject: NoSubject::class,
    method: HttpMethod::Get,
)]
class PhpApiSymbolOp
{
    public static function handle(mixed $subject, Request $request, mixed $actor): PhpApiSymbolData
    {
        abort_unless(app(PhpApiSurface::class)->readable($actor instanceof Authenticatable ? $actor : null), 404);
        $fqn = PhpApiSymbolInputData::from($request->query())->fqn;
        $symbol = is_string($fqn) && $fqn !== '' ? app(PhpApiArtifact::class)->symbol($fqn) : null;
        abort_if($symbol === null, 404);

        return PhpApiSymbolData::from($symbol);
    }
}
